        .gyt-coord-name { font-size: 12.5px; font-weight: 700; color: #00643C; margin-top: 3px; }
        .gyt-collapse-btn {
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 8px;
          width: 100%;
          padding: 8px 10px;
          background: transparent;
          border: none;
          border-radius: 10px;
          color: #8a96a3;
          font-size: 12px;
          font-weight: 500;
          cursor: pointer;
          transition: background 0.15s, color 0.15s;
          white-space: nowrap;
        }
        .gyt-collapse-btn:hover { background: #f0f2f5; color: #5a6472; }
        .gyt-collapse-label {
          opacity: 0;
          transition: opacity 0.2s;
          overflow: hidden;
        }
        .gyt-sidebar.expanded .gyt-collapse-label,
        .gyt-sidebar.mobile-visible .gyt-collapse-label {
