          gap: 8px;
          background: #f6faf8;
          border: 1px solid #d1ead9;
          border-radius: 40px;
          padding: 5px 12px 5px 5px;
          cursor: pointer;
          transition: background 0.15s;
        }
        .gyt-user-btn:hover { background: #e8f5ee; }
        .gyt-avatar {
          width: 30px;
          height: 30px;
          border-radius: 50%;
          background: #00643C;
