        }
        .gyt-user-name { font-size: 13px; font-weight: 600; color: #0d1f2d; }
        .gyt-user-role { font-size: 11px; color: #8a96a3; }
        .gyt-user-chevron { color: #8a96a3; transition: transform 0.15s; }
        .gyt-user-chevron.open { transform: rotate(180deg); }
        .gyt-user-dropdown {
          position: absolute;
          top: calc(100% + 8px);
