        }
        .gyt-dropdown-item {
          display: flex;
          align-items: center;
          gap: 10px;
          padding: 9px 12px;
          border-radius: 8px;
          font-size: 13px;
          color: #5a6472;
          cursor: pointer;
          transition: background 0.12s;
          border: none;
          background: transparent;
