        }
        .gyt-dropdown-item:hover { background: #f0f2f5; color: #0d1f2d; }
        .gyt-dropdown-item.danger:hover { background: #fff5f5; color: #dc2626; }
        .gyt-content-wrap { flex: 1; overflow-y: auto; }
        .gyt-stats-bar {
          display: flex;
          gap: 14px;
          padding: 28px 24px 12px;
          flex-wrap: wrap;
        }
        .gyt-content { padding: 0; }
        .gyt-sidebar-overlay {
