          position: fixed;
          inset: 0;
          background: rgba(0,0,0,0.3);
          z-index: 40;
        }
        .gyt-sidebar-overlay.active { display: block; }
        @media (max-width: 768px) {
          .gyt-sidebar {
            position: fixed;
            left: 0;
            top: 0;
            bottom: 0;
            width: 260px;
            z-index: 50;
            transform: translateX(-100%);
            transition: transform 0.25s ease;
            box-shadow: 0 0 20px rgba(0,0,0,0.1);
          }
          .gyt-sidebar.mobile-visible { transform: translateX(0); }
          .gyt-sidebar.mobile-hidden { transform: translateX(-100%); }
          .gyt-sidebar-overlay.active { display: block; }
          .gyt-stats-bar { padding: 20px 16px 8px; }
          .gyt-topbar { padding: 0 16px; }
        }
        @media (min-width: 769px) {
          .gyt-sidebar { transform: translateX(0) !important; }
        }
        /* Estilos propios del contenido */
        .error-alert, .success-alert {
          padding: 14px 18px;
          border-radius: 28px;
          margin-bottom: 24px;
          font-size: 14px;
          font-weight: 500;
        }
        .error-alert {
          background: #fff5f5;
          border-left: 4px solid #e53e3e;
          color: #c53030;
        }
        .success-alert {
          background: #e8f5e9;
          border-left: 4px solid #2e7d32;
          color: #1b5e20;
        }
        .no-data {
          text-align: center;
          padding: 60px 20px;
          background: #fafcff;
          border-radius: 24px;
          border: 1.5px dashed #cbd5e1;
